// QS Studio - QS program data: decode, edit and re-encode a 350-byte program.
// Parameter layout comes from the Alesis "QS6,7,8,R MIDI SYSEX SPECIFICATION" (Feb 1997),
// see core/qs_params_table.inc (generated by tools/gen_params.py).
#pragma once
#include <optional>
#include <string>

#include "qs_sysex.h"

namespace qs {

struct ParamDef {
    const char* name;
    int lowBit;     // bit position within the 85-byte sound (drum params: within drum 1)
    int bits;
    int offset;     // displayed value = raw + offset
    int limit;      // highest raw value per the spec
    int func, page, pot;  // opcode 10 addressing (Program mode)
};

constexpr int kSoundCount = 4, kSoundBytes = 85, kDrumsPerSound = 10, kDrumStrideBits = 64;
inline int soundByteOffset(int sound) { return 10 + kSoundBytes * sound; }

int keyboardParamCount();
const ParamDef& keyboardParam(int i);
int findKeyboardParam(const std::string& name);  // -1 if not found
int drumParamCount();
const ParamDef& drumParam(int i);

// Function numbers (opcode 10) grouped the way the QS front panel groups them.
const char* functionName(int func);

// Labels with a source. Return "" when unknown, so callers show the number instead.
const char* sampleGroupName(int group);  // 0-15 manual order, verified on factory programs; 24 = Rhythm (factory loops)
const char* lfoWaveName(int v);          // QS7/8 manual: 8 choices

class Program {
public:
    Program() : data(kProgramBytes, 0) {}
    static std::optional<Program> fromDump(const Bytes& msg);  // opcode 00 or 02
    static std::optional<Program> fromData(const Bytes& data350);

    std::string name() const;
    void setName(const std::string& n);

    bool isDrum(int sound) const;
    bool isEnabled(int sound) const;

    int raw(int sound, const ParamDef& p, int drum = 0) const;
    void setRaw(int sound, const ParamDef& p, int raw, int drum = 0);
    int value(int sound, const ParamDef& p, int drum = 0) const { return raw(sound, p, drum) + p.offset; }
    // Highest raw value the editor should allow: the spec limit, widened if this program already exceeds it.
    int editLimit(int sound, const ParamDef& p, int drum = 0) const;
    void setValue(int sound, const ParamDef& p, int value, int drum = 0);

    Bytes editDump() const;              // opcode 02, edit buffer 0 (Program mode)
    Bytes userDump(int programNumber) const;  // opcode 00: writes a User program on the QS

    const Bytes& bytes() const { return data; }

private:
    int bitBase(int sound, const ParamDef& p, int drum) const { return soundByteOffset(sound) * 8 + p.lowBit + drum * kDrumStrideBits; }
    Bytes data;
};

// Opcode 10 live edit. mode: 0 Global, 1 Mix, 2 Program, 3 Effects. value is the displayed (signed) value.
Bytes paramEdit(int mode, int func, int soundOrBus, int page, int channel, int pot, int value);
Bytes paramEdit(const ParamDef& p, int sound, int value);  // Program mode, channel 0

Bytes editProgramRequest(int editNumber = 0);  // opcode 03
Bytes modeSelect(int mode);                    // opcode 0D: 0 Program, 1 Mix

}  // namespace qs
